from __future__ import annotations

import argparse
import ast
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
MODULES = (
    "config", "schemas", "metadata", "document_parser", "chunker", "bm25_index", "embeddings",
    "vector_index", "reranker", "hybrid_search", "diagnostics", "artifacts", "retriever",
)


def export(destination: Path) -> None:
    pieces = [
        "# Generated by scripts/export_retrieval.py from retrieval/*.py.",
        "from __future__ import annotations",
    ]
    for name in MODULES:
        file = ROOT / "retrieval" / f"{name}.py"
        source = file.read_text(encoding="utf-8")
        skipped = {
            i for node in ast.parse(source).body if isinstance(node, ast.ImportFrom)
            and (node.level or node.module == "__future__")
            for i in range(node.lineno, node.end_lineno + 1)
        }
        lines = [line for i, line in enumerate(source.splitlines(), 1) if i not in skipped]
        pieces.append(f"# --- retrieval/{name}.py ---\n" + "\n".join(lines).strip())
    result = "\n\n\n".join(pieces) + "\n"
    compile(result, str(destination), "exec")
    destination.write_text(result, encoding="utf-8")


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description="Export the root-only Python module for the online submission.")
    parser.add_argument("--output", type=Path, default=ROOT / "retrieval_runtime.py")
    export(parser.parse_args().output)
